import{_ as t,o as i,c as l,a2 as n}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"10.4 照明常见故障与检修","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-4-zhao-ming-chang-jian-gu-zhang-yu-jian-xiu.md","filePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-4-zhao-ming-chang-jian-gu-zhang-yu-jian-xiu.md","lastUpdated":1793096070000}'),o={name:"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-4-zhao-ming-chang-jian-gu-zhang-yu-jian-xiu.md"};function e(r,a,s,d,h,c){return i(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="_10-4-照明常见故障与检修" tabindex="-1">10.4 照明常见故障与检修 <a class="header-anchor" href="#_10-4-照明常见故障与检修" aria-label="Permalink to &quot;10.4 照明常见故障与检修&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>灯不亮、灯闪、灯暗……检修照明故障要&quot;由外到内、由易到难&quot;。这一节掌握最常见的故障现象、原因和排查思路,并牢记检修安全。</p><h2 id="一、常见故障现象与原因" tabindex="-1">一、常见故障现象与原因 <a class="header-anchor" href="#一、常见故障现象与原因" aria-label="Permalink to &quot;一、常见故障现象与原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>常见原因</th></tr></thead><tbody><tr><td><strong>灯完全不亮</strong></td><td>灯泡烧坏、保险丝/断路器跳闸、开关触点坏、线路断路、接线松脱</td></tr><tr><td><strong>灯忽亮忽灭/闪烁</strong></td><td>灯丝/触点接触不良、接线松动、荧光灯启辉器或镇流器坏</td></tr><tr><td><strong>灯光暗(亮度不足)</strong></td><td>电压过低、灯泡老化、灯罩积尘、线路太长/太细</td></tr><tr><td><strong>一开灯就跳闸</strong></td><td>短路(火零线相碰)、灯头内短路、绝缘损坏漏电</td></tr><tr><td><strong>荧光灯不启动</strong></td><td>灯管老化、启辉器坏、镇流器坏、灯管漏气</td></tr></tbody></table><h2 id="二、检修的思路-先简单后复杂" tabindex="-1">二、检修的思路(先简单后复杂) <a class="header-anchor" href="#二、检修的思路-先简单后复杂" aria-label="Permalink to &quot;二、检修的思路(先简单后复杂)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 看开关、保险/断路器 —— 跳没跳闸、有没有熔断</span></span>
<span class="line"><span>2. 换灯泡 / 测灯泡 —— 最简单先试</span></span>
<span class="line"><span>3. 查接线 —— 松没松、断没断</span></span>
<span class="line"><span>4. 查线路 —— 用试电笔/万用表测火线、零线有无电</span></span>
<span class="line"><span>5. 查灯具内部 —— 荧光灯换启辉器、镇流器</span></span></code></pre></div><blockquote><p>💡 口诀:<strong>&quot;先开关,后灯泡,再接线,再线路&quot;</strong>——从最省事的查起,别一上来就拆灯。</p></blockquote><h2 id="三、判断线路有没有电" tabindex="-1">三、判断线路有没有电 <a class="header-anchor" href="#三、判断线路有没有电" aria-label="Permalink to &quot;三、判断线路有没有电&quot;">​</a></h2><ul><li>用<strong>试电笔</strong>测开关、灯头接线端子,氖泡亮说明火线有电;</li><li>用<strong>万用表</strong>测火线与零线之间电压,应为 220V 左右;</li><li>测到火线有电、零线没电压,可能是零线断线;</li><li>测灯头火线没电,故障在开关或开关之前的线路。</li></ul><blockquote><p>⚠️ 测电工具:试电笔测&quot;有没有电&quot;,万用表测&quot;电压多少&quot;,两者配合用。</p></blockquote><h2 id="四、检修安全要点-必背" tabindex="-1">四、检修安全要点(必背) <a class="header-anchor" href="#四、检修安全要点-必背" aria-label="Permalink to &quot;四、检修安全要点(必背)&quot;">​</a></h2><ul><li><strong>断电检修</strong>:检修前先断开本回路(或总)开关,并<strong>验电确认无电</strong>;</li><li>站在<strong>干燥的绝缘物</strong>上操作,穿绝缘鞋;</li><li>一人检修,有人监护更好;</li><li>更换灯泡前先关灯,用干布垫着防烫(灯泡刚熄还很热);</li><li>怀疑线路带电时,<strong>用试电笔验电</strong>,不能徒手摸。</li></ul><blockquote><p>⚠️ 判断题高频:<strong>检修电气故障必须先断电、验电</strong>;严禁带电作业(低压电工原则上停电检修)。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 灯全不亮:先查开关、保险/断路器,再查灯泡、线路。</li><li>✅ 荧光灯不启动:检查灯管、启辉器、镇流器。</li><li>✅ 检修三原则:<strong>断电、验电、监护/绝缘</strong>。</li><li>⚠️ 易混点:灯暗(电压低/老化)与灯闪(接触不良)原因不同,对症下药。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>常见故障:不亮、闪烁、变暗、跳闸,各有常见原因。</li><li>排查从&quot;开关、灯泡、接线、线路&quot;逐步来。</li><li>检修安全永远是第一位:先断电、再验电。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)照明线路检修前,应先断开电源并验电。( )</li><li>(单选)一只灯不亮,而其他灯正常,最可能的原因是()。 A. 总开关跳闸　B. 该灯的灯泡损坏或该支路断线　C. 全楼停电　D. 变压器故障</li><li>(判断)荧光灯不启动,可能是启辉器损坏。( )</li><li>(单选)用试电笔测灯头接线端子,氖泡不亮,说明()。 A. 火线断线或开关断开　B. 零线断线　C. 灯泡坏了　D. 电压过高</li><li>(判断)检修照明故障时,可以带电直接用手摸接线端子检查。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。先断电、验电再检修。</li><li><strong>B</strong>。单只灯不亮,问题在本灯或本支路。</li><li><strong>√</strong>。启辉器损坏会导致荧光灯不启动。</li><li><strong>A</strong>。灯头火线无电,说明火线断线或开关断开。</li><li><strong>×</strong>。严禁带电徒手检查,必须断电验电。</li></ol></details>`,21)])])}const p=t(o,[["render",e]]);export{u as __pageData,p as default};
